UPDATE public.notification_templates SET body_template = replace(body_template, '{{lucro_prefixo}}: R$ {{lucro_valor_abs}}', '{{lucro_sinal_valor}}') WHERE type IN ('op_geral','status_operacao') AND body_template LIKE '%lucro_prefixo%'; SELECT o.name, t.type, t.body_template FROM public.notification_templates t JOIN public.operations o ON o.id = t.operation_id WHERE t.type IN ('op_geral','status_operacao') ORDER BY o.name;